-- The setup secret, generated by this migration on the first deploy so nobody has to choose one
-- and it never passes through a form, a URL or an environment variable. No endpoint ever returns
-- it: the Owner reads it from this table with their Netlify login (README "Set up").
--
-- gen_random_uuid() draws 122 random bits from Postgres's cryptographically strong random source,
-- far more than the setup API's rate limit (30 requests a minute per IP) lets anyone guess. To
-- replace the secret, delete the row (the site stores a new one on its next setup request) or set
-- your own of 32+ characters.

CREATE TABLE setup_secret (
  id     boolean PRIMARY KEY DEFAULT true CHECK (id),
  secret text    NOT NULL CHECK (char_length(secret) >= 32)
);

INSERT INTO setup_secret (secret)
VALUES (gen_random_uuid()::text);
